import { StructuredLogger } from '../logging/structured-logger';
import { forEachSequential } from '../common/async-sequence';
import { isAllowedTool } from './unified-agent-tool-parser.helpers';
import { parseToolArgs } from './unified-agent-tool-parser.helpers';
import type { ActionEntry, ToolArgs } from './unified-agent.types';

type UnknownRecord = Record<string, unknown>;

export async function processUnifiedAgentToolCalls(
  deps: {
    executeToolAction: (
      workspaceId: string,
      contactId: string,
      phone: string,
      tool: string,
      args: ToolArgs,
      context?: UnknownRecord,
    ) => Promise<unknown>;
    logAutopilotEvent: (
      workspaceId: string,
      contactId: string,
      tool: string,
      args: Record<string, unknown>,
      result: unknown,
    ) => Promise<unknown>;
    logger: StructuredLogger;
  },
  params: {
    workspaceId: string;
    contactId: string;
    phone: string;
    allowedTools?: string[];
    context?: UnknownRecord;
    toolCalls: Array<{
      type: string;
      function: { name: string; arguments?: string };
    }>;
  },
): Promise<ActionEntry[]> {
  const actionsList: ActionEntry[] = [];

  await forEachSequential(params.toolCalls, async (toolCall) => {
    if (toolCall.type !== 'function') {
      return;
    }
    const toolName = toolCall.function.name;
    if (!isAllowedTool(toolName, params.allowedTools)) {
      deps.logger.warn(
        `Blocked disallowed agent tool call: workspaceId=${params.workspaceId} tool=${toolName}`,
      );
      const blockedResult = { blocked: true, reason: 'capability_not_allowed' };
      actionsList.push({ tool: toolName, args: {}, result: blockedResult });
      await deps.logAutopilotEvent(params.workspaceId, params.contactId, toolName, {}, blockedResult);
      return;
    }
    const toolArgs = parseToolArgs(toolCall, deps.logger);
    const result = await deps.executeToolAction(
      params.workspaceId,
      params.contactId,
      params.phone,
      toolName,
      toolArgs,
      params.context,
    );
    actionsList.push({ tool: toolName, args: toolArgs, result });
    await deps.logAutopilotEvent(
      params.workspaceId,
      params.contactId,
      toolName,
      toolArgs,
      result,
    );
  });

  return actionsList;
}

